def simulate(doc: Dict[str, Any], scope: str, inputs: List[Dict[str, Any]],
             params: Dict[str, Any], start: Optional[int]=None,
             horizon: Optional[int]=None) -> List[Dict[str, Any]]:
    """
    Forward model that reproduces the hidden outcomes for the given scope.
    It uses only the provided `inputs` and `params`.  The model works by
    inspecting the **original** table structure for the scope to learn
    which columns are considered derived (contain “Change”, “$”, or “%”).
    It then recomputes those derived values from the year columns that
    appear in the inputs.  An additional outcome for the row label is
    generated when that row contains at least one derived value.
    """
    # locate all tables in the scope
    table_nodes = [n for n in scope_nodes(doc, scope) if n.get("kind") == "table"]

    # Quick lookup: input values by (node_id, r_index, col) -> amount
    input_lookup = {}
