        # parse the id to get node_id, r_index, col
        parts = inp["id"].split(":")
        node_id, r_index, col = parts[1], int(parts[2]), parts[3]
        input_lookup[(node_id, r_index, col)] = inp["fields"]["amount"]

    # helper to find column index quickly
    def find_col(node, name):
        return node["table"]["columns"].index(name)

    outcomes_out = []

    for node in table_nodes:
        cols = node["table"]["columns"]
        year_cols = [c for c in cols if _year_regex.search(c)]
        derived_cols = [c for c in cols
                        if ("change" in c.lower() or "$" in c or "%" in c)]
        for r_index, row in table_rows(node):
            first_col = cols[0]
            desc = row.get(first_col, "").strip()
            if not desc:
                continue
            ent_id = f"entity:{_sanitize_id(desc)}"
            col_has_value = False
            # produce derived outcomes
            for col in derived_cols:
                raw = row.get(col, "")
                if raw == "":
                    continue
                if "%" in col:
                    val = _parse_number(raw)
                elif "$" in col:
                    # keep raw string for change$ like "$(12,830)"
                    val = raw
                else:
                    # other cases
                    val = _parse_number(raw)
                col_has_value = True
                out_id = _result_id("outcome", node["node_id"], r_index, col)
                outcomes_out.append({
                    "id": out_id,
                    "time": None,
                    "kind": "derived",
                    "entities": [ent_id],
                    "value": val,
                    "src": [[node["node_id"], r_index, [col]]]
                })
            # also add an outcome for the row label if it had any derived value
            if col_has_value:
                out_id = _result_id("outcome", node["node_id"], r_index, "row_label")
                # Use only string, no numeric conversion
                outcomes_out.append({
                    "id": out_id,
                    "time": None,
                    "kind": "derived",
                    "entities": [ent_id],
                    "value": desc,
                    "src": [[node["node_id"], r_index, []]]
                })
    return outcomes_out

