def simulate(doc: Dict[str, Any],
             scope: str,
             inputs: List[Dict[str, Any]],
             params: Dict[str, Any],
             start: Optional[int] = None,
             horizon: Optional[int] = None) -> List[Dict[str, Any]]:
    """
    Forward model that reproduces the hidden outcomes for each scope.

    The model uses only the explicit *inputs* list.  It reconstructs
    derived columns (those containing “Change”, “$”, or “%”) from the
    year column values provided in the inputs.  For each derived column a
    separate outcome record is created.
    """
    # Build lookup from (node_id, row_idx, year_col_name) -> numeric value
    input_lookup: Dict[tuple, int] = {}
    for inp in inputs:
        parts = inp["id"].split(":")
        node_id, r_index, col = parts[1], int(parts[2]), parts[3]
        input_lookup[(node_id, r_index, col)] = inp["fields"]["amount"]

    outcomes: List[Dict[str, Any]] = []

    for table in scope_nodes(doc, scope):
        if table.get("kind") != "table":
            continue

        cols = table["table"]["columns"]
        year_cols = [c for c in cols if _year_regex.search(c)]
        if len(year_cols) < 2:
            continue
        # Map year names to year ints
        year_map = {c: int(_year_regex.search(c).group(1)) for c in year_cols}
        # Identify derived columns (anything with "$", "%" or containing "Change")
        derived_cols = [c for c in cols
                        if ("change" in c.lower() or "$" in c or "%" in c)
                        and c not in year_cols]

        for r_index, row in table_rows(table):
            first_col = cols[0]
            desc = row.get(first_col, "").strip()
            if not desc:
                continue
            ent_id = f"entity:{_sanitize_id(desc)}"

            for col in derived_cols:
                # we compute from input data values of the two year columns
                y_prev, y_curr = year_cols[1], year_cols[0]  # 2018 then 2019
                val_prev = input_lookup.get((table["node_id"], r_index, y_prev))
                val_curr = input_lookup.get((table["node_id"], r_index, y_curr))
                if val_prev is None or val_curr is None:
                    continue

                if "$" in col:
                    # Change in dollars
                    diff = val_curr - val_prev
                    if diff < 0:
                        # format with leading $ and parentheses
                        val = f"$({abs(int(diff)):,})"
                    else:
                        val = int(diff)
                elif "%" in col:
                    # Percent change, integer rounded
                    pct = round((val_curr - val_prev) * 100 / val_prev)
                    val = pct
                else:
                    # any other numeric derived column (not in these samples)
                    pct = round((val_curr - val_prev) * 100 / val_prev)
                    val = pct

                out_id = _result_id("outcome", table["node_id"], r_index, col)
                outcomes.append({
                    "id": out_id,
                    "time": None,
                    "kind": "derived",
                    "entities": [ent_id],
                    "value": val,
                    "src": [[table["node_id"], r_index, [col]]]
                })

    return outcomes

