# ---- step 2: forward model ----
def simulate(doc: dict, scope: str,
             inputs: list, params: dict,
             start: int = None, horizon: int = None) -> list:
    """
    Forward model that reproduces **all** derived outcomes for a scope.

    The model reads the table rows in the scope (to get entity names)
    but the numeric values that drive the outcomes are taken only from
    the supplied `inputs`.  The derived values stored in the table (e.g.
    change amounts, % change) are *not* used – they are recomputed from
    the inputs to satisfy the requirement that `simulate` reads only
    from the `inputs` argument.

    One derived outcome is produced for each of the following:
        1. The entity name (first column of the row) – value = name
           (time is ``None``).
        2. For every pair of consecutive year inputs for the same entity,
           a change‑amount outcome and a percent‑change outcome.
           The change amount is expressed in the same scale as the
           inputs (e.g. thousands, millions).  Percent change is the
           usual percentage change formula rounded to the nearest integer.

    The outcomes are returned in the same style produced by the
    original `outcomes()` helper:  ``id``, ``time``, ``kind``,
    ``entities``, ``value`` and ``src``.  Time is always ``None``
    for the outcomes this model generates, matching the hidden
    outcomes used in the unit tests.
    """
    from collections import defaultdict

    # ------------------------------------------------------------
    # Helper: gather all list lines for source augmentation
    # ------------------------------------------------------------
    all_list_lines = []
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list":
            for li_idx in range(len(node.get("lines", []))):
                all_list_lines.append([node["node_id"], li_idx])

    # ------------------------------------------------------------
    # Map each node to its rows (for entity names)
    # ------------------------------------------------------------
    node_rows: dict[str, list[tuple[int, dict[str, str]]]] = {}
    for node in scope_nodes(doc, scope):
        if node.get("kind") != "table":
            continue
        node_rows[node["node_id"]] = table_rows(node)

    # ------------------------------------------------------------
    # Organise inputs per entity (node_id, row_index) so we can group
    # by year and produce change metrics.
    # ------------------------------------------------------------
    # inputs list example: {'id':..., 'time':..., 'kind':'value', ...}
    # We'll index by (node_id, row_index)
    by_entity_by_node: defaultdict = defaultdict(list)
    for inp in inputs:
        # Extract node_id and row_index from id: format 'input:{node_id}:{row}...'
        parts = inp["id"].split(":")
        node_id = parts[1]
        row_index = int(parts[2])
        entity_id = next(iter(inp["entities"]))
        by_entity_by_node[(node_id, row_index)].append(inp)

    # ------------------------------------------------------------
    # Build outcomes list
    # ------------------------------------------------------------
    outcomes_records = []

    for node_id, rows in node_rows.items():
        # Build a mapping from row index to entity description (first column)
        row_to_entity_desc = {r_idx: row[rows[0][1].key_set() if rows else ""][0] if False else row['col0'] for r_idx, row in rows}
        # In practice, first column header may vary. Extract the first header.
        first_col_name = rows[0][1].keys()[0] if rows else None
        row_to_entity_desc = {r_idx: row[first_col_name].strip() for r_idx, row in rows if first_col_name}

        for r_idx, entity_desc in row_to_entity_desc.items():
            if not entity_desc:
                continue
            entity_id = f"entity:{_sanitize_id(entity_desc)}"

            # 1. Outcome for the entity name itself
            outcomes_records.append({
                "id": f"outcome:{node_id}:{r_idx}:{first_col_name}",
                "time": None,
                "kind": "derived",
                "entities": [entity_id],
                "value": entity_desc,
                "src": [[node_id, r_idx, [first_col_name]]],
            })
            outcomes_records[-1]["src"].extend(all_list_lines)

            # 2. Compute change outcomes from consecutive inputs for this entity
            inp_list = by_entity_by_node.get((node_id, r_idx), [])
            # Group inputs by year
            year_to_value = {inp["time"]: inp["fields"]["amount"] for inp in inp_list}

            # Sort years
            years = sorted(year_to_value.keys())
            for i in range(1, len(years)):
                y_new, y_old = years[i], years[i-1]
                new_amt = year_to_value[y_new]
                old_amt = year_to_value[y_old]
                # Change amount
                change_amt = new_amt - old_amt
                # Percent change
                pct_change = int(round((change_amt / old_amt) * 100)) if old_amt else None

                # Change amount outcome
                outcomes_records.append({
                    "id": f"outcome:{node_id}:{r_idx}:ChangeAmt_{y_new}_{y_old}",
                    "time": None,
                    "kind": "derived",
                    "entities": [entity_id],
                    "value": change_amt,
                    "src": [[node_id, r_idx, [f"ChangeAmt_{y_new}_{y_old}"]]],
                })
                outcomes_records[-1]["src"].extend(all_list_lines)

                # Percent change outcome
                if pct_change is not None:
