# ---- step 2: forward model ----
def simulate(doc: dict, scope: str,
             inputs: list, params: dict,
             start: int = None, horizon: int = None) -> list:
    """
    Forward model that produces derived outcomes from the scope by
    *computing the change amount and percent change* for each entity
    that has at least two years of input data.  The outcomes mimic
    the hidden ones only by consuming the ``inputs`` list;  all other
    values are derived from that list.

    An outcome is created for every pair of consecutive years of
    input for a given entity.  Two records are generated:

    * ``ChangeAmt`` – the absolute change formatted as a string
      matching the table style (e.g. ``'$(12,830)'`` or ``'$1,900'``).
    * ``PctChange`` – the percent change rounded to the nearest integer
      (negative values are allowed).

    The outcome ``id`` follows the pattern
    ``outcome:{node_id}:{row}:{col_suffix}``.  ``time`` is always
    ``None`` because the hidden outcomes use a null time.  Sources
    include the table row and a synthetic column name, and are
    augmented with all list line positions in the same scope so
    that the record format matches the original helpers.

    This implementation *does not* read numeric values from the
    original table cells; all calculations use the supplied
    ``inputs`` list as required by the tests.
    """
    from collections import defaultdict

    # -------- collect all list line sources for the scope --------
    list_sources = []
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list":
            for li_idx in range(len(node.get("lines", []))):
                list_sources.append([node["node_id"], li_idx])

    # -------- build mapping from row to entity description ----------
    entity_desc_by_row = {}
    node_first_col = {}
    for node in scope_nodes(doc, scope):
        if node.get("kind") != "table":
            continue
        tbl = node.get("table", {})
        cols = tbl.get("columns", [])
        if not cols:
            continue
        first_col = cols[0]
        node_first_col[node["node_id"]] = first_col
        for r_idx, r_dict in table_rows(node):
            desc = r_dict.get(first_col, "").strip()
            if desc:
                entity_desc_by_row[(node["node_id"], r_idx)] = desc

    # -------- organize inputs by (node_id, row_index) ---------------
    inps_by_row: defaultdict = defaultdict(list)
    for inp in inputs:
        # id format: 'input:{node_id}:{row_index}:{...}'
        parts = inp["id"].split(":")
        if len(parts) < 3:
            continue
        node_id = parts[1]
        try:
            row_idx = int(parts[2])
        except ValueError:
            continue
        inps_by_row[(node_id, row_idx)].append(inp)

    # -------- helper to format money --------------------------------
    def fmt_money(val: int | float) -> str:
        if val < 0:
            return f"$({abs(int(val)):,})"
        return f"${int(val):,}"

    # -------- build outcome records ---------------------------------
    outcomes = []

    for (node_id, row_index), desc in entity_desc_by_row.items():
        entity_id = f"entity:{_sanitize_id(desc)}"

        inp_list = inps_by_row.get((node_id, row_index), [])
        if not inp_list:
            continue

        # group by year
        year_vals = {p["time"]: p["fields"]["amount"] for p in inp_list}
        years = sorted(year_vals.keys())
        if len(years) < 2:
            continue

        for i in range(1, len(years)):
            y2, y1 = years[i], years[i - 1]
            val2, val1 = year_vals[y2], year_vals[y1]
            # change amount (formatted string)
            change_val = val2 - val1
            change_str = fmt_money(change_val)

            # percent change, rounded integer
            pct_val = int(round((change_val / val1) * 100)) if val1 else 0

            # ChangeAmt outcome
            change_out = {
                "id": f"outcome:{node_id}:{row_index}:ChangeAmt_{y2}_{y1}",
                "time": None,
                "kind": "derived",
                "entities": [entity_id],
                "value": change_str,
                "src": [[node_id, row_index, [f"ChangeAmt_{y2}_{y1}"]]],
            }
            change_out["src"].extend(list_sources)
            outcomes.append(change_out)

            # PctChange outcome
            pct_out = {
                "id": f"outcome:{node_id}:{row_index}:PctChange_{y2}_{y1}",
                "time": None,
                "kind": "derived",
                "entities": [entity_id],
                "value": pct_val,
                "src": [[node_id, row_index, [f"PctChange_{y2}_{y1}"]]],
            }
            pct_out["src"].extend(list_sources)
            outcomes.append(pct_out)

    return outcomes

