def simulate(doc: dict, scope: str,
             inputs: list, params: dict,
             start: int = None, horizon: int = None) -> list:
    """
    Forward model that creates derived outcomes for a given scope.

    The model implements the *change‑amount* and *percent‑change* rules
    that are implicitly present in the reports.  All numeric values are
    taken exclusively from the supplied ``inputs`` list – the original
    table cells are never read.  For every pair of consecutive years
    for a given entity we generate two outcomes:

    * Change amount – stored as a numeric value (the difference of the
      two amounts, sign preserved).
    * Percent change – stored as an integer rounded to the nearest
      percent.

    Additionally an outcome is produced for the entity description
    (first column of the row) with its value as a string.

    All records are returned with the same structure that the original
    `outcomes()` helper uses: ``id``, ``time`` (always ``None``), ``kind``,
    ``entities``, ``value`` and ``src``.  The source refers to the table
    row and a synthetic column name, then is augmented with the
    list‑line positions in the same scope so the record format matches
    the original data.
    """
    from collections import defaultdict

    # ------- collect list line sources for the scope -------
    list_sources = []
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list":
            for li_idx in range(len(node.get("lines", []))):
                list_sources.append([node["node_id"], li_idx])

    # ------- map rows to entity descriptions -------
    entity_desc_by_row = {}
    first_col_by_node = {}
    for node in scope_nodes(doc, scope):
        if node.get("kind") != "table":
            continue
        cols = node.get("table", {}).get("columns", [])
        if not cols:
            continue
        first_col = cols[0]
        first_col_by_node[node["node_id"]] = first_col
        for r_idx, r_dict in table_rows(node):
            desc = r_dict.get(first_col, "").strip()
            if desc:
                entity_desc_by_row[(node["node_id"], r_idx)] = desc

    # ------- group inputs by (node_id, row_index) -------
    inps_by_row: defaultdict = defaultdict(list)
    for inp in inputs:
        # id format 'input:{node_id}:{row_index}:...'
        parts = inp["id"].split(":")
        if len(parts) < 3:
            continue
        node_id = parts[1]
        try:
            row_idx = int(parts[2])
        except ValueError:
            continue
        inps_by_row[(node_id, row_idx)].append(inp)

    # ------- helper to format money when needed ----------
    def fmt_money(val: int | float) -> str:
        if val < 0:
            return f"$({abs(int(val)):,})"
        return f"${int(val):,}"

    # ------- build outcome records ------------------------
    outcomes = []

    for (node_id, row_idx), desc in entity_desc_by_row.items():
        entity_id = f"entity:{_sanitize_id(desc)}"

        # Entity description outcome
        outcomes.append({
            "id": f"outcome:{node_id}:{row_idx}:entity_desc",
            "time": None,
            "kind": "derived",
            "entities": [entity_id],
            "value": desc,
            "src": [[node_id, row_idx, ["entity_desc"]]] + list_sources,
        })

        # Process inputs for this row
        inp_list = inps_by_row.get((node_id, row_idx), [])
        if not inp_list:
            continue

        # group by year
        year_vals = {p["time"]: p["fields"]["amount"] for p in inp_list}
        years = sorted(year_vals.keys())
        if len(years) < 2:
            continue

        for i in range(1, len(years)):
            y2, y1 = years[i], years[i - 1]
            val2, val1 = year_vals[y2], year_vals[y1]
            change_val = val2 - val1
            pct_val = int(round((change_val / val1) * 100)) if val1 else 0

            # Change amount outcome (numeric)
            outcomes.append({
                "id": f"outcome:{node_id}:{row_idx}:ChangeAmt_{y2}_{y1}",
                "time": None,
                "kind": "derived",
                "entities": [entity_id],
                "value": change_val,
                "src": [[node_id, row_idx, [f"ChangeAmt_{y2}_{y1}"]]] + list_sources,
            })

            # Percent change outcome (integer)
            outcomes.append({
                "id": f"outcome:{node_id}:{row_idx}:PctChange_{y2}_{y1}",
                "time": None,
                "kind": "derived",
                "entities": [entity_id],
                "value": pct_val,
                "src": [[node_id, row_idx, [f"PctChange_{y2}_{y1}"]]] + list_sources,
            })

    return outcomes

